def max_chain_length(pairs, length):
    # Define a helper function to perform depth-first search (DFS) on subarrays
    def dfs(start, current_length, path):
        # If the current length is greater than the desired length
        if current_length >= length:
            return 1
        max_length = 0
        # Explore all possible subarrays ending at the current end
        for end in range(start, len(pairs)):
            # Compose a new path with the current pair
            new_path = path + [pairs[end]]
            # Recursively find the maximum chain length in the new subarray
            max_length = max(max_length, dfs(end + 1, current_length + 1, new_path))
        return max_length

    # Start DFS from all possible starting points
    return max(dfs(0, 1, []), length)
