from typing import List

def largest_subset(nums: List[int], n: int) -> int:
    """
    Find the largest subset where each pair is divisible.

    Args:
    nums: List of positive integers.
    n: Number of elements in the list.

    Returns:
    The largest subset with divisible pairs.
    """
    def is_divisible(x, y):
        return x % y == 0

    subsets = []
    for i in range(n + 1):
        for subset in subsets:
            if is_divisible(subset[-1], nums[i - 1]):
                subset.append(nums[i - 1])
        if subset and len(subset) > len(subsets[-1]):
            subsets[-1] = subset[:]
    return len(subsets[-1])

