def max_sum_of_three_consecutive(arr, n):
    # Initialize variables to store the maximum sum
    max_sum = arr[0]
    for i in range(1, n):
        # If the current number is greater, update the maximum sum
        if arr[i] > arr[i - 1] + arr[i - 2]:
            max_sum = arr[i]
        else:
            # Update the maximum sum if the current number is equal to the sum of the two preceding numbers
            max_sum = max(max_sum, arr[i] + arr[i - 1])
        # Update the maximum sum if the current number is greater than the sum of the maximum three numbers found so far
        if max_sum > arr[i] + arr[i - 1] + arr[i - 2]:
