def sum_Of_Primes(n):
    if n < 2:
        return 0  # As there are no prime numbers less than 2

    # Initialize a list to track prime numbers
    is_prime = [True] * (n + 1)
    p = 2

    # Implementing the Sieve of Eratosthenes
    while (p * p <= n):
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    # Sum up all prime numbers
    return sum(p for p in range(2, n + 1) if is_prime[p])

