def removals(arr: List[int], k: int, m: int) -> int:
    # Remove one element that's all larger than k from the array unless there are at least m elements
    if len(arr) >= m:
        return len(arr) - m
    else:
        # Rearrange the array to find the smallest possible difference from m elements
        return num_smaller(arr, k)

def num_smaller(arr: List[int], k: int) -> int:
    # Use a two-pointer approach to find the smallest difference
    i, j = 0, len(arr) - 1
    min_diff = float('inf')

    while i < j:
        diff = arr[j] - arr[i]
        # Update min_diff if the current smallest difference is smaller
        if diff < min_diff:
            min_diff = diff
        # Move the pointers towards the center if the current element is larger than k
        if arr[j] > k:
            j -= 1
        else:
            i += 1

    return min_diff

