    # Function to check if a number is prime
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    count = 0
    # Prime factorization of the input number
    while number > 1:
        # Count the number of power of each prime factor
        while number % is_prime(number):
            count += 1
            number //= is_prime(number)
