def maxAverageOfPath(matrix, n):
    visited = [[False for _ in range(n)] for _ in range(n)]
    leftMax = [0] * n
    rightMax = [0] * n
    upMax = [0] * n
    downMax = [0] * n
    maxAverage = 0

    def dfs(currentX, currentY):
        if currentX == n - 1 and currentY == n - 1:
            nonlocal maxAverage
            maxAverage = max(maxAverage, sum(matrix[currentX][currentY]) / n)
            return

        visited[currentX][currentY] = True
        for nextX in range(currentX + 1, n):
            if upMax[nextX] == 0:
                dfs(nextX, currentY)
            else:
                leftMax[currentX] += matrix[currentX][nextX]

        for nextY in range(currentY + 1, n):
            if rightMax[nextY] == 0:
                dfs(currentX, nextY)
            else:
                downMax[currentY] += matrix[currentX][nextY]

        for nextX in range(currentX, 0, -1):
            if downMax[nextX] == 0:
                dfs(nextX, currentY)
            else:
                leftMax[currentX] -= matrix[currentX][nextX]

        for nextY in range(currentY, 0, -1):
            if upMax[nextY] == 0:
                dfs(nextX, currentY)
            else:
                rightMax[currentY] -= matrix[currentX][nextY]

        # Backtrack: restore visited
        upMax[currentX], rightMax[currentX], downMax[currentX], leftMax[currentX] = 0, 0, 0, 0

    dfs(0, 0)
    return maxAverage

