def find_Index(n):
    def triangular_number(index):
        return index * (index + 1) // 2

    # Initialize the smallest triangular number and its corresponding index
    smallest_triangular = float('inf')
    smallest_index = -1

    # Iterate over possible indices to find the smallest triangular number
    for i in range(n + 1):
        triangular_num = triangular_number(i)
        if triangular_num < smallest_triangular:
            smallest_triangular = triangular_num
            smallest_index = i

