def check_expression(expression):
    # Initialize counters for parentheses
    open_parentheses, close_parentheses = 0, 0

    # Iterate through each character in the expression
    for char in expression:
        if char == '{':
            open_parentheses += 1
        elif char == '}':
            close_parentheses += 1

        # If there are more closing parentheses than opening ones, it's unbalanced
        if close_parentheses > open_parentheses:
            return False

    # If both counters are equal, the expression is balanced
    return open_parentheses == close_parentheses

