def generate_matrix(n):
    matrix = [[0 for _ in range(n)] for _ in range(n)]
    top, bottom, left, right = 0, n-1, 0, n-1
    value = 1

    while True:
        # Fill the top row starting from top
        for i in range(left, right+1):
            matrix[top][i] = value
            value += 1

        # Fill the right column starting from right
        for i in range(top, bottom+1):
            matrix[i][right] = value
            value += 1

        # Fill the bottom row starting from bottom
        if top < bottom:
            for i in range(right, left-1, -1):
                matrix[bottom][i] = value
                value += 1

        # Fill the left column starting from left
        if left < right:
            for i in range(bottom, top-1, -1):
                matrix[i][left] = value
                value += 1

        # If we've filled all the matrix, exit the loop
        if top > bottom or left > right:
            break

    return matrix

