"""
def generate_matrix(n):
    """
    Generates a square matrix filled with elements from 1 to n raised to the power of 2 in spiral order.
    """
    matrix = [[None] * n for _ in range(n)]
    bottom, top, right, left, increment = 0, n - 1, n - 1, 0, 1
    while left <= right and top <= bottom:
        for i in range(left, right + 1):
            matrix[top][i] = (i + 1) ** increment
        if top < bottom:
            for j in range(top + 1, right + 1):
                matrix[j][right] = (j + 1) ** increment
        if right > left:
            for j in range(right - 1, left - 1, -1):
                matrix[bottom][j] = (j + 1) ** increment
        if bottom > top:
            for i in range(bottom - 1, top - 1, -1):
                matrix[i][left] = (i + 1) ** increment
        left += increment
        right -= increment
        top += increment
        bottom -= increment
    return matrix

