def min_Swaps(s1, s2):
    # Count the number of different characters in both strings
    count1 = {}
    count2 = {}

    for char in s1:
        if char in count1:
            count1[char] += 1
        else:
            count1[char] = 1

    for char in s2:
        if char in count2:
            count2[char] += 1
        else:
            count2[char] = 1

    # Find the common characters and count the minimum number of swaps needed
    common_chars = []
    for char in count1:
        if char in count2:
            common_chars.append(char)

    # Calculate the minimum number of swaps required
    total_swaps = sum(abs(count1[char] - count2[char]) * 2 for char in common_chars)

    return total_swaps

