def nth_super_ugly_number(k: int, primes: List[int]) -> int:
    # Initialize a heap with the first ugly numbers
    min_heap = []  # Max heap, i.e., size k
    for prime in primes[:k]:
        heapq.heappush(min_heap, prime)

    used = set([prime] for prime in primes[:k])

    # Continue until there are no more candidates to be added to the heap
    while min_heap:
        current_prime = heapq.heappop(min_heap)
        # Add its multiples to the heap
        for next_prime in primes:
            if next_prime <= current_prime and next_prime not in used:
                heapq.heappush(min_heap, next_prime)
                used.add(next_prime)

    # The top element of the heap is the nth super ugly number
    return heapq.heappop(min_heap)

