def n_common_words(text, n):
    # Split the text into words
    words = text.split()

    # Count the occurrences of each word
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    # Find the most common n words
    most_common_words = sorted(word_count.items(), key=lambda x: (-x[1], x[0]))

    # Return the top n most common words
    return most_common_words[:n]

