def max_sum_subseq(arr):
    def max_crossing_subseq(arr, low, n):
        if low == n:
            return 0

        # Recursively find left and right max sum ends at arr[idx]
        idx = low
        left_max = arr[low]
        for i in range(low + 1, n):
            if arr[i] > left_max:
                left_max = arr[i]

        # Recursively find right max sum ends at arr[idx]
        right_max = arr[n - 1]
        for i in range(n - 2, low - 1, -1):
            if arr[i] > right_max:
                right_max = arr[i]

        # Return the maximum of left_max, right_max, and the sum of arr[i] with or without taking arr[i]
        return max(left_max + arr[idx], right_max + arr[idx], arr[idx])

    # Initialize result
    result = -1

    # Iterate through the array and continue the exploring 
    for i in range(len(arr)):

        # Traverse both halves separately to find maximum sum subsequence
        max_high = max_crossing_subseq(arr, i, len(arr))
        max_low = max_crossing_subseq(arr, 0, i)

        # Store the maximum of all possible subsequences found
        result = max(result, max_high + 10000, max_low + 10000)

    return result

