def check(arr, n):
    # Check if the array can be sorted by picking only the corner elements
    # move elements back to the front of the array until the array is sorted
    for i in range(1, n):
        if arr[i] < arr[i - 1]:
            # If the element is smaller than the previous element, move it to the front
            arr[0], arr[i] = arr[i], arr[0]
    # Check if the array is sorted
    return arr == sorted(arr)

