def max_product(arr):
    """
    Find a pair with the highest product from a given array of integers.

    Args:
    arr (list of int): The input array of integers.

    Returns:
    tuple: A tuple (a, b) where a is the largest product and b is the second largest product.
    """
    if len(arr) < 2:
        return None

    maximum1 = float('-inf')
    maximum2 = float('-inf')
    minimum1 = float('inf')
    minimum2 = float('inf')

    for num in arr:
        if num > maximum1:
            maximum2 = maximum1
            maximum1 = num
        elif num > maximum2:
            maximum2 = num

        if num < minimum1:
            minimum2 = minimum1
            minimum1 = num
        elif num < minimum2:
            minimum2 = num

    return (maximum1, minimum2)

