def subset(nums, n):
    if n == 0 or n == 1:
        return n

    # Iterate over each number in the array
    for i in range(n):
        # Recursively find the minimum number of subsets with distinct elements
        # that include all elements from nums[:i]+nums[i+1:]
        if i == 0:
            res = 1
        else:
            res = res + subset(nums[:i], i) + subset(nums[i+1:], n-i-1)

