        for j in range(i + 1):
            if j == 0:
                triangle[i][0] += triangle[i][1]
            elif j == len(triangle[i]) - 1:
                triangle[i][j] += triangle[i][-1]
            else:
                triangle[i][j] += min(triangle[i][j - 1], triangle[i][j + 1])

